    correctOptionIndex: 2,
    difficulty: 'medium',
    cognitiveLevel: 'apply',
    explanation: '',  // TODO: redação pedagógica pendente
    sourceTheme: 'Concordância',
    tags: ['eaar','eear','port','concordância','prova-oficial'],
    expectedTime: 180,
    source: 'EEAR CFS 2020 - questão 14 (gabarito oficial: C)',
