    stimulus: {
      type: 'text',
      content: 'LÍNGUA PORTUGUESA Como os campos Marina Colasanti 1 Preparavam-se aqueles jovens estudiosos para a vida adulta, acompanhando um sábio e ouvindo seus ensinamentos. Porém, como fizessse cada dia mais frio com o adiantar-se do outono, dele se aproximaram e perguntaram: 5 – Senhor, como devemos vestir-nos? – Vistam-se como os campos - respondeu o sábio. Os jovens então subiram a uma colina e durante dias olharam para os campos. Depois dirigiram-se à cidade, onde compraram tecidos de muitas cores e fios de muitas fibras. 10 Levando cestas carregadas, voltaram para junto do sábio. Sob o seu olhar, abriram os rolos das sedas, desdobraram as peças de damasco e cortaram quadrados de veludo, e os emendaram com retângulos de cetim. Aos poucos, foram criando, em longas vestes, os campos arados, o vivo verde dos 15 campos em primavera, o pintalgado da germinação. E entremearam fios de ouro no amarelo dos trigais, fios de prata no alagado das chuvas, até chegarem ao branco brilhante da neve. As vestes suntuosas estendiam-se como mantos. O sábio nada disse. 20 Só um jovem pequenino não havia feito sua roupa. Esperava que o algodão estivesse em flor, para colhê-lo. E quando teve os tufos, os fiou. E quando teve os fios, os teceu. Depois vestiu sua roupa branca e foi para o campo trabalhar. Arou e plantou. Muitas e muitas vezes sujou-se de terra. E 25 manchou-se do sumo das frutas e da seiva das plantas. A roupa já não era branca, embora ele a lavasse no regato. Plantou e colheu. A roupa rasgou-se, o tecido puiu-se. O jovem pequenino emendou os rasgões com fios de lã, costurou remendos onde o pano cedia. E quando a neve veio, prendeu 30 em sua roupa mangas mais grossas para se aquecer. Agora a roupa do jovem pequeno era de tantos pedaços, que ninguém poderia dizer como havia começado. E estando ele lá fora uma manhã, com os pés afundados na terra para receber a primavera, um pássaro o confundiu com o campo e 35 veio pousar no seu ombro. Ciscou de leve entre os fios, sacudiu as penas. Depois levantou a cabeça e começou a cantar. Ao longe, o sábio, que tudo olhava, sorriu. Colasanti, M. Mais de 100 histórias maravilhosas - 1.ed. –São Paulo: Global, 2015. As questões de 01 a 04 referem-se ao texto acima.',
      source: 'EEAR CFS 2020 - questão 21',
    },
    question: 'Em qual alternativa o nome Maria não é um vocativo?',
    options: [
      { label: 'a) “Maria, o teu nome principia Na palma da minha mão”' },
      { label: 'b) “É o tempo, Maria Te comendo feito traça Num vestido de noivado”' },
      { label: 'c) “João amava Teresa que amava Raimundo que amava Maria que amava Joaquim que amava Lili”' },
      { label: 'd) “E agora, Maria? O amor acabou a filha casou O filho mudou”' },
    ],
    correctOptionIndex: 2,
    difficulty: 'medium',
    cognitiveLevel: 'apply',
    explanation: '',  // TODO: redação pedagógica pendente
