    question: 'De acordo com o Anuário Nacional de Emissões de Vapores Combustíveis de Automóveis, em 1989 cada veículo leve emitia 5 g/dia de gasolina na forma de vapor para a atmosfera. Os últimos dados de 2012 do anuário, indicam que cada veículo leve emite apenas 0,15 g/dia de gasolina, na forma de vapor para a atmosfera. A diminuição na quantidade de combustível emitido para a atmosfera se deve a presença nos carros atuais de um dispositivo chamado cânister que absorve a maior parte dos vapores de gasolina que seriam emitidos para a atmosfera durante a exposição do carro parado ao sol e depois os injeta diretamente na câmara de combustão durante o funcionamento do motor. A quantidade de calor necessária para vaporizar a gasolina absorvida pelo cânister por dia é, em joules, igual a _______. Considere: 1 - o calor latente de vaporização do combustível igual a 400 J/g; 2 - a gasolina de 1989 idêntica a utilizada em 2012.',
