      type: 'text',
      content: '1 A linguagem — a fala humana — é uma inesgotável riqueza de múltiplos valores. A linguagem é inseparável do homem e segue-o em todos os seus atos. A linguagem é o instrumento graças ao qual o homem modela seu 5 pensamento, seus sentimentos, suas emoções, seus esforços, sua vontade e seus atos, o instrumento graças ao qual ele influencia e é influenciado, a base última e mais profunda da sociedade humana. Mas é também o recurso último e indispensável do homem, seu refúgio nas horas solitárias em 10 que o espírito luta com a existência, e quando o conflito se resolve no monólogo do poeta e na meditação do pensador. Antes mesmo do primeiro despertar de nossa consciência, as palavras já ressoavam à nossa volta, prontas para envolver os primeiros germes frágeis de nosso pensamento e a nos 15 acompanhar inseparavelmente através da vida, desde as mais humildes ocupações da vida quotidiana aos momentos mais sublimes e mais íntimos dos quais a vida de todos os dias retira, graças às lembranças encarnadas pela linguagem, força e calor. A linguagem não é um simples acompanhante, mas 20 sim um fio profundamente tecido na trama do pensamento; para o indivíduo, ela é o tesouro da memória e a consciência vigilante transmitida de pai para filho. Hjelmslev, Louis. Prolegômenos a uma teoria da linguagem. As questões de 01 a 04 referem-se ao texto acima.',
