    id: 'eaar-2022-ing-058',
    bancaId: 'eaar',
    discipline: 'Inglês',
    stimulus: {
      type: 'text',
      content: 'Fires and Hurricanes In the US, fires burn in the west. Also, hurricanes hit the east. However, extreme weather is more and more usual in all of the world. Scientists think that human activity brings more extreme weather. The planet is getting warmer. A study finds that people are responsible for 97% of fires in the US. Warmer temperatures mean more fires. The fires start very easily. They are bigger. It is harder to stop them. Warmer temperatures also make more hurricanes. The hurricanes are stronger. It is more common that they get the land. They break up houses. They kill people, too. Scientists expect more hurricanes this year. The hurricane season ends on November 30th. https://www.newsinlevels.com/products/fires-and-hurricanes-level-1/',
      source: 'EEAR CFS 2022 - questão 42',
    },
    question: 'Without changing the meaning, the phrasal verb in bold in the sentence below can be substituted for “She is very upset because it’s been one year since her father passed away.”',
