    discipline: 'Matemática',
    question: 'Uma caixa cúbica, de aresta 10 cm, está totalmente cheia de água. Ao despejar toda a água num tubo cilíndrico de 5 cm de raio, essa água atingirá a altura de ____/π cm no tubo. (Considere as dimensões como sendo internas aos recipientes e que o tubo tem a altura necessária para o evento.)',
