    stimulus: {
      type: 'text',
      content: 'LÍNGUA PORTUGUESA Divagação sobre as ilhas Carlos Drumnond de Andrade Quando me acontecer alguma pecúnia, passante de um milhão de cruzeiros, compro uma ilha; não muito longe do litoral, que o litoral faz falta; nem tão perto, também que de lá possa eu aspirar a fumaça e a graxa do porto. Minha ilha (e só de a imaginar já me considero seu habitante) ficará no justo ponto de latitude e longitude, que, pondo-me a coberto de ventos, sereias e pestes, nem me afaste demasiado dos homens nem me obrigue a praticá-los diuturnamente. Porque esta é a ciência e, direi, a arte do bem-viver; uma fuga relativa, e uma não muito estouvada confraternização. De há muito sonho esta ilha, se é que não a sonhei sempre. (...) E por que nos seduz a ilha? As composições de sombra e luz, o esmalte das relvas, a cristalinidade dos regatos – tudo isso existe fora das ilhas, não é privilégio dela. A mesma solidão existe, com diferentes pressões, nos mais diversos locais, inclusive os de população densa, em terra firme e longa. Resta ainda o argumento da felicidade – “aqui eu não sou feliz”, declara o poeta, para enaltecer, pelo contraste, a sua pasárgada: mas será que se procura realmente nas ilhas uma ocasião de ser feliz ou modo de sê-lo? E só se alcançaria tal mercê, de índole extremamente subjetiva, no regaço de uma ilha, e não igualmente em terra comum? Quando penso em comprar uma ilha, nenhuma dessas excelências me seduz mais que as outras, nem todas juntas constituem a razão de meu desejo. (...) A ilha me satisfaz por ser uma porção curta de terra (falo de ilhas individuais, não me tentam aventuras marajoaras), um resumo prático, substantivo, dos estirões deste vasto mundo, sem os inconvenientes dele, e com a vantagem de ser quase ficção sem deixar de constituir uma realidade. Presença da Literatura Brasileira. Modernismo. 5a. edição. As questões de 01 a 04 referem-se ao texto acima.',
      source: 'EEAR CFS 2024 - questão 06',
    },
    question: 'Ao reescrever o trecho A secretária chega à sala da diretora e diz: “Senhora, passarei nas salas de aula para dar o recado.” para o discurso indireto, o verbo em destaque assume a seguinte forma:',
    options: [
      { label: 'a) passaria.' },
      { label: 'b) passará.' },
      { label: 'c) ia passar.' },
      { label: 'd) vai passar.' },
    ],
