    id: 'eaar-2021-ing-135',
    bancaId: 'eaar',
    discipline: 'Inglês',
    stimulus: {
      type: 'text',
      content: 'Can you recognize your emotions? If I ask you how you are feeling, you may answer: “I’m feeling good, I’m fine”! But what does that “good” or “fine” really mean? Would it mean fascinated, curious, balanced, joyful, encouraged, hopeful, motivated, happy? On the other hand you might also reply: “I’m feeling bad”, and, then, recognize that you are feeling bored, lonely, sorry, anxious, fearful, nervous, insecure or frustrated. The advantage of making such distinctions, rather than feeling “good” or “bad” is that your emotions indicate what you need to do to feel more satisfying. For example, if you are angry with a person, you can argue with him, you can request him to stop his offensive behavior or you can avoid him. You have choices. Recognize each of your emotions and pay attention to what they are communicating to you. Adapted from Inglês no mundo do trabalho.',
      source: 'EEAR CTA 2021 - questão 31',
    },
