    discipline: 'Inglês',
    stimulus: {
      type: 'text',
      content: 'Diary: your life day by day Most people consider diaries indispensable - a reminder of what they have to do each day. This is especially true in the professional world. A diary can help you keep track of your agenda and make it easier for you to follow a planned schedule. In this sense, it is similar to a notebook with dates in which you write meetings and other things to remember. At school or at work, diaries are very useful. However, a diary can be more than a list of appointments: it can be a secret record of private thoughts. People write these diaries for different reasons: for fun or to read them years later. “It makes you think and form an opinion on what you are writing” - when you express your feelings and experiences, it’s easier to overcome your problems; it’s like a therapy. Nowadays, some people write e-diaries, called blogs or web logs. “They open their hearts” to other people on the Net. In fact, many people, famous or ordinary in fiction or in real life, write diaries. Adapted from Inglês de olho no mundo do trabalho.',
      source: 'EEAR CTA 2021 - questão 33',
    },
    question: 'According to the text, we can infer that______________________.',
    options: [
      { label: 'a) Our emotions are divided only between good and bad' },
      { label: 'b) It’s very easy to identify if our emotions are good or bad' },
      { label: 'c) You have no choice when you are annoyed with somebody' },
      { label: 'd) Our emotions may indicate what we need to do to feel happier a nº 7 Read the text and answer questions 34 and 35. Diary: your life day by day Most people consider diaries indispensable - a reminder of what they have to do each day. This is especially true in the professional world. A diary can help you keep track of your agenda and make it easier for you to follow a planned schedule. In this sense, it is similar to a notebook with dates in which you write meetings and other things to remember. At school or at work, diaries are very useful. However, a diary can be more than a list of appointments: it can be a secret record of private thoughts. People write these diaries for different reasons: for fun or to read them years later. “It makes you think and form an opinion on what you are writing” - when you express your feelings and experiences, it’s easier to overcome your problems; it’s like a therapy. Nowadays, some people write e-diaries, called blogs or web logs. “They open their hearts” to other people on the Net. In fact, many people, famous or ordinary in fiction or in real life, write diaries. Adapted from Inglês de olho no mundo do trabalho.' },
    ],
