    id: 'eaar-2023-ing-186',
    bancaId: 'eaar',
    discipline: 'Inglês',
    stimulus: {
      type: 'text',
      content: 'Giant floating robots and millennia-old odors make up a new installation at Tate Modern Museum Aimee Dawson Two species of intelligent robots have moved into some prime, Thames-side real estate: Tate Modern’s Turbine Hall. Collectively named “aerobes,” the floating orbs that the New York-based artist Anicka Yi has created to inhabit the cavernous space are called “planulae” and “xenojellies”. Inspired by ocean life forms and mushrooms, ___ helium-filled shapes move around using rotors and ___ small battery pack. Together, they create ___ “ecosystem” within ___ museum, Yi said in a press statement, interacting with their environment and visitors, and displaying individual and group behaviors. Behind the scenes, an incredible amount of AI technology and research is powering this floating family. A team of specialists has developed the aerial vehicles using software that gives each a unique flight path. The software, called an artificial life program, generates a huge range of journey options for the orbs to take and therefore simulates the somewhat unpredictable processes of natural life. Págin The robots will respond to the space and people around them by receiving information from electronic sensors positioned around the venue. The signals affect them individually and as a group so that they will behave differently upon each encounter. “Like a bee’s dance or an ant’s scent trail, the aerobes communicate with each other in ways we cannot understand,” a Tate Modern statement described. Yi is also using her aerobes to question ideas around intelligence and our focus on the brain as its main transmitter. Adapted from https://edition.cnn.com/style/article/anicka-yi-tate-modern- turbine-hall/index.html. Access on October 14th, 2021.',
      source: 'EEAR CTA 2023 - questão 44',
    },
    question: 'Choose the alternative that correctly completes the comic strip. I NEVER SHOULD ______ ______ ON THIS CHEAP AIRLINE Taken from https://www.thecomicstrips.com/subject/The-Airplane+Pilot-Comic- Strips.php',
