    bancaId: 'eaar',
    discipline: 'Inglês',
    stimulus: {
      type: 'text',
      content: 'Passenger with no flying experience lands plane after pilot incapacitated A passenger without any flying experience safely landed a plane at a Florida airport after the pilot became incapacitated. The Federal Aviation Administration was investigating the incident. It was believed the pilot may have suffered a medical emergency. In a statement, the FAA said two passengers were onboard the single-engine Cessna 208 when the pilot had a “possible medical issue”. One passenger steered the private plane smoothly into Palm Beach international airport. According to LiveATC.net audio, the passenger told air traffic control: “I’ve got a serious situation here. My pilot has gone incoherent and I have no idea how to fly the airplane”. The air traffic controller then asked what his position was. He replied: “I see the cost of Florida in front of me and I have no idea”. “We’re trying to locate you”, the controller said. After four minutes, air traffic control located the plane, which was off Boca Raton. The controller proceeded to guide the passenger through the descent. In a video obtained by CNN, the plane can be seen landing slowly and smoothly. In a separate recording, another air traffic controller can be heard telling pilots: “you just witnessed a couple of passengers land that plane.” (Adapted from www.theguardian.com)',
      source: 'EEAR CTA 2024 - questão 28',
    },
    question: '“...A terrorist incident at Gran Canaria airport had caused many flights to be diverted to Los Rodeos...” According to this sentence from the text, we can affirm that many aircraft _________.',
