      content: 'Read the text and answer questions 25, 26, 27 and 28. Tenerife Airport disaster The Tenerife Airport disaster occurred on March 27, 1977, when two Boeing 747 passenger jets collided on the runway at Los Rodeos Airport, on the Spanish Island of Tenerife. The collision occurred when KLM flight 4805 initiated its takeoff run while Pan Am Flight 1736 was still on the runway. The impact and resulting fire killed everyone on board KLM 4805 and most of the occupants of Pan Am 1736, with only 61 survivors in the front section of the aircraft. Resulting in 583 fatalities, the disaster is the deadliest accident in aviation history. A terrorist incident at Gran Canaria Airport had caused many flights to be diverted to Los Rodeos, including the two aircraft involved in the accident. The airport quickly became congested with parked airplanes blocking the only taxiway and forcing departing aircraft to taxi on the runway instead. Patches of thick fog were drifting across the airfield; hence visibility was greatly reduced for pilots and the control tower. The subsequent investigation by Spanish Authorities concluded that the primary cause of the accident was the KLM captain’s decision to take off in the mistaken belief that a takeoff clearance from air traffic control had been issued. (Adapted from Wikipedia).',
