export function getEAARByDiscipline(d: string): UserQuestion[] {
  return EAAR_QUESTIONS.filter(q => q.discipline === d);
}
export function getEAARByTheme(t: string): UserQuestion[] {
  return EAAR_QUESTIONS.filter(q => q.sourceTheme === t);
}
export const EAAR_STATS = {
  total: EAAR_QUESTIONS.length,
  byDiscipline: EAAR_QUESTIONS.reduce<Record<string, number>>((a, q) => {
    a[q.discipline] = (a[q.discipline] || 0) + 1; return a;
  }, {}),
};